@startuml

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + EmailAddress : string
}

class ScheduledPickup {
  + StreetAddress : string
  + ItemDescription : string
  + PickupTime : time
}

class Vehicle {
  + StorageSpace : double
}

class Route {
  + Day : date
}

class VolunteerDriver {
  + AvailableDays : string[]
}

class Article {
  + Description : string
  + Category : string
}

class DistributionCenter {
  + Location : string
}

class H2SEmployee {
  + Name : string
}

class Client {
  + HomeAddress : string
  + NeededCategories : string[]
}

class FoodBank {
  + Name : string
}

class FoodItem {
  + Description : string
}

class SecondHandArticle {
  + Description : string
  + RFIDTag : string
}

class PickupRoute {
  + Day : date
}

Resident "1" -- "*" ScheduledPickup : schedules
ScheduledPickup "1" -- "1" Vehicle : assigned to
ScheduledPickup "1" -- "1" VolunteerDriver : driven by
Vehicle "1" -- "1" PickupRoute : follows
VolunteerDriver "1" -- "*" PickupRoute : operates
PickupRoute "1" -- "*" ScheduledPickup : contains
PickupRoute "1" -- "1" VolunteerDriver : assigned to

Article "*" -- "1" DistributionCenter : processed at
H2SEmployee "1" -- "*" Article : examines
Article "1" -- "1" SecondHandArticle : is a
Article "1" -- "1" FoodItem : is a

SecondHandArticle "*" -- "1" DistributionCenter : dropped off at
FoodItem "*" -- "1" FoodBank : dropped off at

Client "1" -- "*" Article : receives
H2SEmployee "1" -- "*" Client : calls
H2SEmployee "1" -- "*" Article : delivers
VolunteerDriver "1" -- "*" Article : delivers

@enduml

